INSERT INTO feature VALUES('io-theory','runtime','The IO of a program as a theory, with a model in the source',NULL,'partial','notable',NULL,'`std.io` states the IO of a program one time as the theory `Io.Eff`: a read, a write and `close_file`, each of which gives its continuation a completion endpoint. The buffer of a read or a write moves into the operation and comes back with its completion, and an error of a model is a negative count at the endpoint. A program over the theory names no model. `Scripted` is the model with no kernel: a forked process in the source answers each operation from a tape of input and output, with a buffer as a list of bytes. A model over the ring and a blocking model are owed, and so is a program that copies its input under each model.',NULL,'library/std/src/io.gandr',NULL,'#7844');
